import{z as l,x as o,o as n,c as d,q as i,j as A,D as E,d as r,s as B,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"财务困境与重组","description":"","frontmatter":{"title":"财务困境与重组","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/financial-distress-restructuring.md","filePath":"econ/financial-distress-restructuring.md","lastUpdated":1791063341000}'),p={name:"econ/financial-distress-restructuring.md"};function c(u,a,D,C,m,h){const t=o("Mermaid");return n(),d("div",null,[a[2]||(a[2]=i('<h1 id="财务困境与重组" tabindex="-1">财务困境与重组 <a class="header-anchor" href="#财务困境与重组" aria-label="Permalink to &quot;财务困境与重组&quot;">​</a></h1><div class="epigraph"><p>财务困境是资本结构把清偿力尚可或本可重组的企业推进了昂贵的谈判；直接费用往往小于间接的客户、雇员与投资扭曲。</p><footer>—— Andrade and Kaplan, How Costly Is Financial (Not Economic) Distress, Journal of Finance 1998；Wruck, Journal of Financial Economics 1990；对照 [直接与间接破产成本](/econ/bankruptcy-direct-indirect)</footer></div><p><a href="/econ/securitization-otd">上一课</a>把表外管道的冻结写成展期失败。主干已有直接/间接成本与积压。本课缺口是进阶：困境中如何重组（私下重组 vs 法庭）、成本何时是财务的而非经济的。不重估律师费百分比，不把第 11 章程序细节提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Andrade–Kaplan（1998）：高杠杆交易样本里，困境企业许多不是经济上该死，成本来自财务结构。Wruck：重组是把要求权再谈判到可继续经营。缺口是动态路径：Leland 的 \\(V_B\\) 一旦靠近，现实不是瞬时破产，而是契约违约、评级悬崖、供应商收缩信用、管理层为生存赌大或投资不足。私下重组省法庭费用，但受制于债权人分散（下一课协调）。</p><p><span class="marginnote">经济困境：资产的无杠杆价值已经低于继续经营所需。财务困境：切片使继续经营的激励与流动性崩溃。权衡要的是后者；前者不是少借债能救的。</span></p><p><span class="marginnote">常见误区：以为困境企业的激励扭曲只有一个方向。股权还剩价值时，股东偏好赌大——赌赢了归自己，赌输了反正是债权人的；股权已经归零、只剩债权人时，公司会反过来拒绝对全体都有利的好项目（债务积压）。同一个困境，两种相反的病，取决于谁还握着剩余索取权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：债务减免与债转股、展期、注入新钱（DIP 在后课）、卖资产、换管理层。私下完成需要几乎全体一致或关键多数；持出（holdout）使重组失败，把企业推入法庭。成本：直接（法律、咨询）对大企业常是价值的小百分比；间接是客户不买耐用品、雇员离开、供应商现金交货——营运资本课的垫付在困境中反转成挤兑。</p><p>与代理：股东在钱里时偏好赌大；债权人偏好过早清算。重组规则决定谁赢，从而决定事前杠杆。这是 Leland 的 \\(\\alpha\\) 与 \\(V_B\\) 的制度基础。</p>',10)),(n(),A(s,null,{default:E(()=>[B(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEAR%5B%22%E9%9D%A0%E8%BF%91%E8%BF%9D%E7%BA%A6%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20PRIV%5B%22%E7%A7%81%E4%B8%8B%E9%87%8D%E7%BB%84%22%5D%0A%20%20NEAR%20--%3E%20COURT%5B%22%E6%B3%95%E5%BA%AD%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20HOLD%5B%22%E6%8C%81%E5%87%BA%22%5D%20--%3E%20COURT%0A%20%20PRIV%20--%3E%20CHEAP%5B%22%E8%B4%B9%E7%94%A8%E4%BD%8E%2C%20%E5%8D%8F%E8%B0%83%E9%9A%BE%22%5D%0A%20%20COURT%20--%3E%20RULE%5B%22%E7%A8%8B%E5%BA%8F%E6%8F%90%E4%BE%9B%E5%A4%9A%E6%95%B0%E5%86%B3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"资本预算：困境不是「WACC 加几个点」能概括。高杠杆项目应把间接成本进现金流情景（客户流失），而不是只加 CRP 式的常数。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是谈判失败的外部性。每个债权人要全额，除非规则强迫减记。资产价值在谈判期间因间接成本融化，使拖延有真实损耗——这是为什么「无摩擦再谈判可以达到第一最佳」在课堂上成立、在样本里不成立。火线出售是资产市场买家不足；重组是要求权市场协调不足。两者在杠杆周期里一起出现。",-1)),(n(),A(s,null,{default:E(()=>[B(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E4%B8%80%E6%AC%A1%E5%88%A9%E6%81%AF%E6%9C%AA%E4%BB%98%EF%BC%9A%E6%8A%80%E6%9C%AF%E8%BF%9D%E7%BA%A6%22%5D%20--%3E%20ACC%5B%22%E5%8A%A0%E9%80%9F%E6%9D%A1%E6%AC%BE%EF%BC%9A%E5%80%BA%E6%9D%83%E4%BA%BA%E8%8E%B7%E5%BE%97%E5%85%A8%E9%A2%9D%E6%B1%82%E5%81%BF%E6%9D%83%22%5D%0A%20%20ACC%20--%3E%20EACH%5B%22%E6%AF%8F%E4%B8%AA%E5%80%BA%E6%9D%83%E4%BA%BA%E9%83%BD%E6%83%B3%E8%A6%81%E5%85%A8%E9%A2%9D%22%5D%0A%20%20EACH%20--%3E%20STALL%5B%22%E8%B0%88%E5%88%A4%E5%83%B5%E4%BD%8F%EF%BC%9A%E6%B2%A1%E4%BA%BA%E8%82%AF%E5%85%88%E5%87%8F%E8%AE%B0%22%5D%0A%20%20STALL%20--%3E%20MELT%5B%22%E6%8B%96%E5%BB%B6%E4%B8%AD%EF%BC%9A%E5%AE%A2%E6%88%B7%E6%B5%81%E5%A4%B1%20%E4%BE%9B%E5%BA%94%E5%95%86%E8%A6%81%E7%8E%B0%E6%AC%BE%22%5D%0A%20%20MELT%20--%3E%20VDROP%5B%22%E8%B5%84%E4%BA%A7%E4%BB%B7%E5%80%BC%E8%9E%8D%E5%8C%96%EF%BC%9A%E6%89%80%E6%9C%89%E4%BA%BA%E7%9A%84%E8%9B%8B%E7%B3%95%E5%8F%98%E5%B0%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">术语翻译：持出（holdout）就是重组里的「钉子户」——减记方案要求每个债权人让步，有人拒绝签字、等着按原价全额受偿。若价值不缩水，当钉子户确实划算；可资产正随拖延融化时，钉子户拉低的恰恰是他自己将来能分到的蛋糕。这正是法庭程序要用多数决替代全票的原因。</span></p><p>与 Jensen：困境可以强迫吐出现金、换经理，是纪律的极端。成熟 FCF 企业的杠杆故意靠近这条线；成长企业靠近则触发积压。样本继续匹配。</p><h3 id="不要把重组成本写成「破产污名」一句" tabindex="-1">不要把重组成本写成「破产污名」一句 <a class="header-anchor" href="#不要把重组成本写成「破产污名」一句" aria-label="Permalink to &quot;不要把重组成本写成「破产污名」一句&quot;">​</a></h3><p>污名是信息：客户更新质量。机制要拆成：合约中断、专用性投资停止、融资挤兑。能合同解决的（第三方担保、预付），应进 APV 减成本；不能的才是真正的 \\(\\alpha\\)。</p><p><span class="marginnote">主干 <a href="/econ/bankruptcy-direct-indirect">bankruptcy-direct-indirect</a> 已拆直接间接。本课把重组路径接上动态资本结构与下一课第 11 章。</span></p><p><span class="marginnote">数字实例：直接成本（律师、顾问费）对大企业常只占公司价值的 1-3%；间接成本可以是两位数——耐用品厂商一出困境消息，客户担心保修落空而停止下单，销售收入掉两成，供应商改要货到付款，营运资本瞬间被抽干。这个量级差说明：把困境成本记成「律师费百分比」会严重低估，间接扭曲才是大头。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成美国破产统计年鉴。下一课专写第 11 章的自动中止、DIP、绝对优先的偏离。再下一课协调与空壳债权人：CDS 使「债权人」可能希望违约。</p><p>后课默认：财务困境成本主要是间接与谈判拖延；私下重组省费用但怕持出。经济困境与财务困境必须分开，否则权衡被冤枉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>财务困境是切片引起的谈判与激励成本，不是资产已经该死。</li><li>私下重组便宜但持出；法庭用程序换多数决。</li><li>间接成本走现金流情景；不要只用加点的 WACC。</li><li>出处：Andrade and Kaplan, <em>JF</em> 1998；Wruck, <em>JFE</em> 1990。</li></ul>',11))])}const _=l(p,[["render",c]]);export{F as __pageData,_ as default};
